import {AlertCircle,Inbox,LoaderCircle,X} from 'lucide-react';
import styles from './ExternalUI.module.css';

const cx=(...values)=>values.filter(Boolean).join(' ');
export const externalWorkspaceClass=styles.workspace;

export function PageHeader({eyebrow,title,subtitle,actions}){return <header className={styles.pageHeader}><div>{eyebrow&&<p className={styles.eyebrow}>{eyebrow}</p>}<h2 className={styles.pageTitle}>{title}</h2>{subtitle&&<p className={styles.subtitle}>{subtitle}</p>}</div>{actions&&<div className={styles.actions}>{actions}</div>}</header>}
export function SectionHeader({title,subtitle,actions}){return <div className={styles.sectionHeader}><div><h3 className={styles.sectionTitle}>{title}</h3>{subtitle&&<p className={styles.subtitle}>{subtitle}</p>}</div>{actions&&<div className={styles.actions}>{actions}</div>}</div>}
export function Surface({as:Tag='section',density='standard',interactive=false,subtle=false,className='',children,...props}){return <Tag className={cx(styles.surface,styles[density],interactive&&styles.surfaceInteractive,subtle&&styles.surfaceSubtle,className)} {...props}>{children}</Tag>}
export function Button({variant='secondary',size='medium',icon:Icon,iconOnly=false,loading=false,children,className='',...props}){const sizeClass=size==='small'?styles.buttonSmall:size==='large'?styles.buttonLarge:'';return <button className={cx(styles.button,styles[variant],sizeClass,iconOnly&&styles.iconOnly,className)} aria-busy={loading||undefined} {...props}>{loading?<LoaderCircle aria-hidden="true" size={16} className="animate-spin"/>:Icon?<Icon aria-hidden="true" size={16}/>:null}{!iconOnly&&children}</button>}
export function Field({label,required=false,helper,error,children}){return <label className={styles.label}>{label}{required&&<span className={styles.required}> *</span>}{children}{error?<span role="alert" className={styles.error}>{error}</span>:helper?<span className={styles.helper}>{helper}</span>:null}</label>}
export function Input(props){return <input className={styles.control} {...props}/>}
export function Select(props){return <select className={styles.control} {...props}/>}
export function TextArea(props){return <textarea className={styles.control} {...props}/>}
export function StatusChip({tone='neutral',icon:Icon,children}){return <span className={cx(styles.status,styles[tone])}>{Icon&&<Icon aria-hidden="true" size={13}/>}<span>{children}</span></span>}
export function ProgressBar({value,label}){const safe=Math.max(0,Math.min(100,Number(value)||0));return <div><div className={styles.progressTrack} role="progressbar" aria-label={label} aria-valuemin="0" aria-valuemax="100" aria-valuenow={safe}><div className={styles.progressValue} style={{width:`${safe}%`}}/></div>{label&&<p className={styles.helper}>{label}: {safe}%</p>}</div>}
export function FeedbackState({kind='empty',title,copy,action}){const Icon=kind==='error'?AlertCircle:Inbox;return <div role={kind==='error'?'alert':undefined} className={styles.feedback}><span className={styles.feedbackIcon}><Icon aria-hidden="true" size={19}/></span><h3 className={styles.feedbackTitle}>{title}</h3>{copy&&<p className={styles.feedbackCopy}>{copy}</p>}{action&&<div className={cx(styles.actions,'mt-4')}>{action}</div>}</div>}
export function LoadingSkeleton({height='8rem',label='Loading content'}){return <div aria-label={label} aria-busy="true" className={styles.skeleton} style={{height}}/>}
export function FilterBar({children,label='Filters'}){return <div aria-label={label} className={styles.filterBar}>{children}</div>}
export function Tabs({items,value,onChange,label='Sections'}){return <div role="tablist" aria-label={label} className={styles.tabs}>{items.map(item=><button key={item.value} role="tab" aria-selected={value===item.value} onClick={()=>onChange(item.value)} className={cx(styles.tab,value===item.value&&styles.tabActive)}>{item.label}</button>)}</div>}
export function DataTable({columns,rows,rowKey='id',mobileRow,empty}){if(!rows.length)return empty||null;return <div className={styles.tableWrap}><table className={cx(styles.table,styles.desktopTable)}><thead><tr>{columns.map(column=><th key={column.key} scope="col">{column.label}</th>)}</tr></thead><tbody>{rows.map(row=><tr key={row[rowKey]}>{columns.map(column=><td key={column.key}>{column.render?column.render(row):row[column.key]}</td>)}</tr>)}</tbody></table>{mobileRow&&<div className={styles.mobileList}>{rows.map(row=><div key={row[rowKey]}>{mobileRow(row)}</div>)}</div>}</div>}
export function Drawer({open,title,subtitle,onClose,children}){if(!open)return null;return <div className={styles.backdrop} onClick={onClose}><section role="dialog" aria-modal="true" aria-label={title} className={styles.drawer} onClick={event=>event.stopPropagation()}><header className={styles.drawerHeader}><div><h2 className={styles.sectionTitle}>{title}</h2>{subtitle&&<p className={styles.subtitle}>{subtitle}</p>}</div><Button icon={X} iconOnly aria-label="Close panel" onClick={onClose}/></header><div className={styles.drawerBody}>{children}</div></section></div>}
